package main

import (
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type WalletService struct {
	balances map[string]int64
	mu       sync.Mutex
}

func NewWalletService() *WalletService {
	return &WalletService{
		balances: map[string]int64{
			"user_alice": 10000,
			"user_bob":   5000,
			"user_carol": 7500,
		},
	}
}

// Transfer handles balance transfers between users via WebSocket
// Protocol: {"action":"transfer","from":"user_alice","to":"user_bob","amount":100}
func (ws *WalletService) Transfer(from, to string, amount int64) (string, error) {
	// Read balance without holding lock through entire operation
	ws.mu.Lock()
	fromBalance := ws.balances[from]
	ws.mu.Unlock()

	// Validation gap - balance check is not atomic with deduction
	if fromBalance < amount {
		return "", fmt.Errorf("insufficient funds: have %d, need %d", fromBalance, amount)
	}

	// Simulate processing delay (e.g., compliance check, logging)
	// This window allows concurrent requests to pass the balance check
	// before either deduction is applied

	ws.mu.Lock()
	ws.balances[from] -= amount
	ws.balances[to] += amount
	newBalance := ws.balances[from]
	ws.mu.Unlock()

	return fmt.Sprintf("transferred %d from %s to %s. new balance: %d", amount, from, to, newBalance), nil
}

func (ws *WalletService) GetBalance(user string) int64 {
	ws.mu.Lock()
	defer ws.mu.Unlock()
	return ws.balances[user]
}

func (ws *WalletService) HandleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		var msg struct {
			Action string `json:"action"`
			From   string `json:"from"`
			To     string `json:"to"`
			Amount int64  `json:"amount"`
		}

		err := conn.ReadJSON(&msg)
		if err != nil {
			log.Printf("read error: %v", err)
			break
		}

		switch msg.Action {
		case "transfer":
			// Each WebSocket message spawns a goroutine for concurrent handling
			go func() {
				result, err := ws.Transfer(msg.From, msg.To, msg.Amount)
				if err != nil {
					conn.WriteJSON(map[string]string{"error": err.Error()})
					return
				}
				conn.WriteJSON(map[string]string{"result": result})
			}()
		case "balance":
			bal := ws.GetBalance(msg.From)
			conn.WriteJSON(map[string]interface{}{"balance": bal, "user": msg.From})
		default:
			conn.WriteJSON(map[string]string{"error": "unknown action"})
		}
	}
}

func main() {
	service := NewWalletService()

	http.HandleFunc("/ws", service.HandleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("ok"))
	})

	log.Println("WebSocket wallet service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
